import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []
    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        max_prod = 0
        # try incrementing each position
        for i in range(n):
            prod = 1
            for j, val in enumerate(a):
                if j == i:
                    prod *= (val + 1)
                else:
                    prod *= val
            if prod > max_prod:
                max_prod = prod
        out_lines.append(str(max_prod))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
